import{S as d,o as s,c,a9 as n,B as r}from"./chunks/framework.DxG24V0C.js";const u=JSON.parse('{"title":"自改 / hooks 桥 / 生态：agent 学会改自己、也接得住别家的协议","description":"","frontmatter":{"title":"自改 / hooks 桥 / 生态：agent 学会改自己、也接得住别家的协议"},"headers":[],"relativePath":"deepseek/08-self-modification-hooks.md","filePath":"deepseek/08-self-modification-hooks.md","lastUpdated":1787409644000}'),a={name:"deepseek/08-self-modification-hooks.md"},p=Object.assign(a,{setup(i){const e=[{question:'`dsh` 的"native hook"到底是什么？',options:["一个 TypeScript 接口","一个订阅拦截点的普通插件","恰好一个 shell 脚本文件","一个 TypeScript 类库"],correct:1,explanation:"核心重构：native hook 不是包，而是订阅 typed-Decision 拦截点的普通 cordis 插件；CC/Codex bridge 只是一层翻译。"},{question:"`dsh-tool-cordis` 这套自引用工具的信任姿态是什么？",options:["作为完整的安全边界","作为强力隔离即安全","sandbox，但不作安全边界","sandbox 能完全阻止宿主访问"],correct:2,explanation:"vm sandbox 隔离全局污染、但不是安全边界；临时库能触到 ctx.fs/bash 的真实权限，所以 trust = bash access、需 opt-in。"},{question:"`dsh-hook-protocol` 属于什么？",options:["一个 cordis 插件","一个库","一个 CDN 资源","一个 NPM 脚本"],correct:1,explanation:"hook-protocol 是 CC/Codex 两个 bridge 共享的 dialect-neutral 库，不注入任何东西，只提供 matcher、run hook、merge 与 hook/* 事件。"},{question:"为什么 hooks 桥存在？",options:["它比原生插件能力更强","它走原生插件走不了的路","兼容已有 hooks 配置","它负责填补安全边界空洞、并守住每一处"],correct:2,explanation:"桥只是兼容路径：把已在 CC/Codex 里养好的 hooks.json 平移进来；真要定制要走原生插件，桥并非最佳做法。"},{question:'下面哪个最能概括 `dsh` 全篇的"引擎"立场？',options:["把全部能力都装进单个大文件里，一次打包完毕且以后也不再改动","typed events + 可变缝 + bridge","闭门自研，并拒绝与任何外部生态做协议互通","把每个任务都拆成一段完全固定的流水线逐一跑完"],correct:1,explanation:"综合全文：统一的 typed event + surface，一切可换 provider、可 bridge 既有协议、可自反扩展，正是 dsh 作为通用引擎的立场。"}];return(l,o)=>{const t=d("Quiz");return s(),c("div",null,[o[0]||(o[0]=n('<h1 id="自改-hooks-桥-生态-agent-学会改自己、也接得住别家的协议" tabindex="-1">自改 / hooks 桥 / 生态：agent 学会改自己、也接得住别家的协议 <a class="header-anchor" href="#自改-hooks-桥-生态-agent-学会改自己、也接得住别家的协议" aria-label="Permalink to &quot;自改 / hooks 桥 / 生态：agent 学会改自己、也接得住别家的协议&quot;">​</a></h1><blockquote><p>本文基于 <code>dsh-v0.1.0-rc.7</code>。项目处于 developer preview，迭代很快，文中机制以该基线为准。</p></blockquote><p>前七篇我们把 <code>dsh</code> 从插件森林、Cordis、agent-loop、会话日志、工具管线、capability 缝，一路看到压缩 / 上下文注入 / 子代理这些&quot;长会话扩展&quot;。现在是收尾的第八篇，聊三件&quot;往更大处收&quot;的事：</p><ol><li><strong>自改（self-modification）</strong>：agent 能不能检查自己当前挂载了哪些插件、并且主动挂载 / 卸载新的临时插件？</li><li><strong>hooks 桥</strong>：已经住在 Claude Code / Codex 生态里的人，他们的 <code>hooks.json</code> 能不能被 <code>dsh</code> 原样接住跑起来？</li><li><strong>生态</strong>：把这八篇的机制串起来看，<code>dsh</code> 作为一个通用引擎，和 OpenCode / Codex / Claude Code 到底差在哪、又靠什么立住。</li></ol><p>先放这一篇的核心判断：</p><blockquote><p><strong><code>dsh</code> 的终局主张是：一切都可扩展，且扩展的接口统一。</strong> 于是它把&quot;agent 改自己&quot;做成一组<strong>自引用的临时组件工具</strong>，把&quot;接住别家 hooks&quot;做成 <strong>hooks 桥（一对应翻译器）</strong>——而这两件事底层都复用一个东西：那套 typed-Decision 拦截点（<code>agent/pre-step</code>、<code>tools/pre-execute</code>、<code>tools/post-execute</code>……）和它背后的 Cordis 事件模型。</p></blockquote><h2 id="一、自改-agent-能不能-看自己-、并-卸了再装" tabindex="-1">一、自改：agent 能不能&quot;看自己&quot;、并&quot;卸了再装&quot; <a class="header-anchor" href="#一、自改-agent-能不能-看自己-、并-卸了再装" aria-label="Permalink to &quot;一、自改：agent 能不能&quot;看自己&quot;、并&quot;卸了再装&quot;&quot;">​</a></h2><h3 id="一个很尴尬的前提-runtime-里全是插件-agent-却看不见" tabindex="-1">一个很尴尬的前提：runtime 里全是插件，agent 却看不见 <a class="header-anchor" href="#一个很尴尬的前提-runtime-里全是插件-agent-却看不见" aria-label="Permalink to &quot;一个很尴尬的前提：runtime 里全是插件，agent 却看不见&quot;">​</a></h3><p>整栏我们都习惯了一个前提——<code>dsh</code> 到处是 cordis 插件。但自引用的动机 Agent Note（<code>interception-extension-points</code> 的同门，<code>self-referential-cordis-toolset</code>）开篇就把那个别扭点破了：</p><blockquote><p>Everything in this harness is a cordis plugin, but the agent running inside that plugin runtime cannot see or touch it: it cannot enumerate the services and events around it, cannot extend itself with a new tool mid-session, and cannot compose capabilities it invents.</p></blockquote><p>一个跑半天、背后有几十个插件的运行时，<strong>里面的 agent 自己却看不见也没法触达这些插件</strong>——没法枚举身边的服务与事件、没法在会话中途给自己加一个新工具、没法当场组装一个自己刚发明的新能力。这就是 <code>dsh</code> 要补的&quot;自改&quot;。</p><h3 id="不是-让模型跑段-js-那么随便-有三个前置问题" tabindex="-1">不是&quot;让模型跑段 js&quot;那么随便，有三个前置问题 <a class="header-anchor" href="#不是-让模型跑段-js-那么随便-有三个前置问题" aria-label="Permalink to &quot;不是&quot;让模型跑段 js&quot;那么随便，有三个前置问题&quot;">​</a></h3><p>把&quot;让模型自己改运行时&quot;交给模型，绝不是&quot;让模型跑段 code&quot;这么草率——设计上先承认三个正确性（correctness）问题并存：</p><ol><li><strong>模型写的注册要在写的那一步就校验</strong>：畸形 tool schema 必须在注册时就失败，而不是拖到下一次请求要把它拼进 prompt 时才炸。</li><li><strong>模型写的代码要调用它从没看过的 service API</strong>：靠猜方法签名、甚至猜返回形状，会白白浪费很多次盲试。</li><li><strong>模型挂载的一切必须完全可卸</strong>：model 能按需卸，宿主插件 reload 时也要能按正常插件生命周期跟着卸——否则长会话会慢慢堆出一批没人管的 listener 和 tool。</li></ol><h3 id="五个自引用的命令-inspect-→-define-→-run-→-stop-→-undefine" tabindex="-1">五个自引用的命令：inspect → define → run → stop → undefine <a class="header-anchor" href="#五个自引用的命令-inspect-→-define-→-run-→-stop-→-undefine" aria-label="Permalink to &quot;五个自引用的命令：inspect → define → run → stop → undefine&quot;">​</a></h3><p>落法在 <code>packages/extensions/tool-cordis</code>（<code>@deepseek-ai/dsh-tool-cordis</code>）这个命名空间插件里。它给了模型五个针对<strong>当前 DSH 进程实时运行时</strong>的工具（不是 shell 脚本，是命令工具）：</p><ul><li><code>cordis_inspect</code> —— 对当前进程的<strong>只读报告</strong>（<code>services</code>/<code>plugins</code>/<code>temporary</code>/<code>tools</code>/<code>api</code>/<code>events</code> 各一节，<code>what:</code> 可精确到一个目标）。<strong>先看得见，才有资格动手。</strong></li><li><code>cordis_define</code> —— 校验并登记一个&quot;动态包&quot;（<code>name</code>、<code>purpose</code>、host half <code>code</code> 或/和 browser half <code>client</code>），对它做语法检查；<strong>只登记、不运行</strong>，取一个进程内的 <code>dyn-&lt;n&gt;</code> id。</li><li><code>cordis_run</code> —— 把该包的 host half 放进 <code>node:vm</code> 沙箱里真正评估，并把 browser half 推送给所有打开的 web 页面。<strong>正在运行的包会重投交付（避免 reload 页面拿不到活体）。</strong></li><li><code>cordis_stop</code> —— 把宿主那一半卸到 quiescence（所拥有的 tool、listener、service、timer、effect 全回到可回构造状态）后返回，<strong>定义本身在，可再 run</strong>。</li><li><code>cordis_undefine</code> —— 先 stop、再 forget：把定义从注册表里忘掉，会话里那张卡片变成&quot;未加载记录&quot;，不能自动提升。</li></ul><p>这一整套的<strong>执行宿主</strong>在 <code>packages/extensions/cordis-host-runner</code>（<code>ctx.dynamicCordisRunner</code>）：定义注册表、<code>node:vm</code> 沙箱与 fiber 生命周期、invoke handler 表、以及浏览器页面承载 run 往返的那一半。<code>tool-cordis</code> 只是壳，没有 runner 就没有沙箱、工具派不上用场。</p><h3 id="沙箱语义-隔离全局污染-但不是安全边界" tabindex="-1">沙箱语义：隔离全局污染，但<strong>不是</strong>安全边界 <a class="header-anchor" href="#沙箱语义-隔离全局污染-但不是安全边界" aria-label="Permalink to &quot;沙箱语义：隔离全局污染，但**不是**安全边界&quot;">​</a></h3><p>动态包跑在 vm realm，但 <code>tool-cordis</code> README 与 Agent Note 反复强调同一个 trust stance：</p><blockquote><p>The sandbox isolates globals but is not a security boundary. …… Treat this toolset like bash access; do not rely on it as a product security boundary.</p></blockquote><ul><li>vm 隔离<strong>意外的全局污染</strong>（Node 全局 <code>process</code>/<code>Buffer</code> 留 <code>undefined</code>，<code>require</code>/<code>fetch</code>/timer 是抛错指向 Cordis 替代品的问路口）；</li><li>但<strong>已授权服务</strong>（<code>ctx.fs</code>、<code>ctx.web</code>、<code>ctx.bash</code>、timer……）拿到的是 host 执行器的权限——这个临时组件真能触达线上运行时；</li><li>所以它<strong>绝不是安全边界</strong>，<code>dsh</code> 明说要像对待 <code>bash</code> 一样对待它、谨慎开启。</li></ul><p>可以说：自改和 bash 是<strong>同一档信任</strong>——能用 bash 的地方就能用它，但它不给你&quot;更安全&quot;。</p><h3 id="装-不难-看得出能卸、真能卸干净-才是设计题" tabindex="-1">&quot;装&quot;不难，&quot;看得出能卸、真能卸干净&quot;才是设计题 <a class="header-anchor" href="#装-不难-看得出能卸、真能卸干净-才是设计题" aria-label="Permalink to &quot;&quot;装&quot;不难，&quot;看得出能卸、真能卸干净&quot;才是设计题&quot;">​</a></h3><p>前几节讲了模型怎么写，真正让&quot;自改&quot;成立的是<strong>管理容器</strong>，不是写插件代码本身：<code>stop</code>/<code>undefine</code> 保证任何自挂的东西都能回到<strong>没挂</strong>状态；运行时全<strong>进程内存</strong>（storage stance：注册表是进程内唯一真源，<code>stop</code>/<code>undefine</code>/toolset 卸载/DSH restart 都会清空，且定义不会自动恢复）；<code>cordis_inspect</code> 先给模型看清&quot;现在挂了什么&quot;，再决定动不动。</p><p>把对齐起来，就是一句话：<strong>自改 = inspect-able（先可看）→ disposable（必可卸）→ validate-at-define（写时即验）。</strong> 模型被当成&quot;被信任的插件作者&quot;，而运行时被要求&quot;可检验地接受、可回退地卸载&quot;。</p><h2 id="二、hooks-桥-把别人的-shell-hook-协议-接进-咱们的-typed-decision" tabindex="-1">二、hooks 桥：把别人的 shell-hook 协议&quot;接进&quot;咱们的 typed Decision <a class="header-anchor" href="#二、hooks-桥-把别人的-shell-hook-协议-接进-咱们的-typed-decision" aria-label="Permalink to &quot;二、hooks 桥：把别人的 shell-hook 协议&quot;接进&quot;咱们的 typed Decision&quot;">​</a></h2><p>如果说&quot;自改&quot;是从内部长出能力，那 hooks 桥就是<strong>从外部接生态</strong>——把 Claude Code / Codex 已经成规模的 <code>hooks</code> 配置，接进 <code>dsh</code> 自己的拦截点。</p><h3 id="一次关键的重构-原生-hook-不是一个包-而是一套事件-api" tabindex="-1">一次关键的重构：&quot;原生 hook&quot;不是一个包，而是一套事件 API <a class="header-anchor" href="#一次关键的重构-原生-hook-不是一个包-而是一套事件-api" aria-label="Permalink to &quot;一次关键的重构：&quot;原生 hook&quot;不是一个包，而是一套事件 API&quot;">​</a></h3><p>拦截扩展点的 Agent Note（<code>interception-extension-points</code>）开头给出了整个 hooks 子系统的地基重构——它几乎把 hooks 定义成&quot;给怎样一个 typed 事件 API 配了翻译器&quot;：</p><blockquote><p>The key reframe driving this design is that <strong>&quot;native hooks&quot; are not a package</strong> — a native hook is just an ordinary cordis plugin subscribing to the canonical lifecycle events. So the real product is a <em>powerful, well-typed canonical event API</em>; the CC and Codex bridges are merely translators that map an external shell-hook protocol onto that same API.</p></blockquote><p>也就是说，<code>dsh</code> 自己的 hook 面落在 <strong>typed-Decision 拦截点</strong> 上（<code>tools/pre-execute</code>、<code>tools/post-execute</code>、<code>agent/pre-step</code>、<code>agent/turn-stopping</code>……），&quot;原生 hook&quot; 就是<strong>在那个面上订阅的普通 cordis 插件</strong>。而 <code>dsh-hooks-claude-code</code> / <code>dsh-hooks-codex</code> 这两个包，<strong>只是把外部 shell-hook 协议翻译到那套 API 的翻译器</strong>——&quot;anything a hook can do, a plain plugin can do directly&quot;。</p><h3 id="真正共享的一半-抽成-hook-protocol-库" tabindex="-1">真正共享的一半，抽成 <code>hook-protocol</code> 库 <a class="header-anchor" href="#真正共享的一半-抽成-hook-protocol-库" aria-label="Permalink to &quot;真正共享的一半，抽成 `hook-protocol` 库&quot;">​</a></h3><p>两块独立桥各自要复用一大半；为避免各写各的，共享核心抽成 <strong><code>@deepseek-ai/dsh-hook-protocol</code></strong>（<code>packages/hooks/hook-protocol/</code>）。它<strong>不是 cordis 插件，不注入任何东西</strong>，是个 dialect-neutral 的库，提供：</p><ul><li><strong>matcher 校验与解释</strong>（<code>matcherDiagnostic</code> / <code>matchesMatcher</code>，<code>claude</code> 模式 = 字面量或正则、<code>codex</code> 恒为正则）；</li><li><strong><code>runHook</code></strong>——真正用 <code>ctx.shell</code> 跑一个 hook（stdin payload、env、timeout），并解码退出码 / stdout；</li><li><strong>结果合并</strong>（<code>mergeHookOutputs</code>：权限 deny &gt; ask &gt; allow，halt 有粘性，block 原因拼接）；</li><li><strong>两个 <code>hook/*</code> 会话事件</strong>——<code>hook/invoked</code> 和 <code>hook/result</code>（log-only、非 surface，<code>appendHookInvoked</code>/<code>appendHookResult</code> 负责落盘和 decision 归属；stderr 摘要截断到 <code>stderrSummaryMaxChars</code>=500）；</li><li>以及那三处 detached 点（<code>SessionStart</code>/<code>SubagentStart</code>/<code>SubagentStop</code>）fire-and-forget 的一致性——<strong>dispose 必须等所有在跑的 hook 进程中止后 resolve</strong>。</li></ul><p>每条 bridge 只保有自己方言那半边：CC 的 stdin payload + <code>${CLAUDE_PLUGIN_ROOT}</code>/<code>${CLAUDE_PROJECT_DIR}</code> 替换 + outcome→Decision 映射；Codex 类比它自己的子集。</p><h3 id="cc-那半边-逐-hook-映射到-typed-decision-most-restrictive" tabindex="-1">CC 那半边：逐 hook 映射到 typed Decision，most-restrictive <a class="header-anchor" href="#cc-那半边-逐-hook-映射到-typed-decision-most-restrictive" aria-label="Permalink to &quot;CC 那半边：逐 hook 映射到 typed Decision，most-restrictive&quot;">​</a></h3><p><code>dsh-hooks-claude-code</code> 把用户现有 <code>hooks.json</code>（或 settings 里的 <code>hooks</code> key）<strong>只取可映射的命令子集</strong>，映射到 typed Decision：</p><table tabindex="0"><thead><tr><th>CC hook</th><th>Harness point</th><th>映射</th></tr></thead><tbody><tr><td><code>SessionStart</code></td><td><code>agent/session-start</code>（emit，不能 block）</td><td>additionalContext → <code>agent.inject()</code>，不能 gate 启动</td></tr><tr><td><code>UserPromptSubmit</code></td><td><code>agent/pre-step</code>（waterfall）</td><td><code>deny</code>→<code>PreStepDecision.reject</code>；否则走 <code>next()</code> 到下游</td></tr><tr><td><code>PreToolUse</code></td><td><code>tools/pre-execute</code>（waterfall）</td><td><code>deny</code>→<code>PreToolDecision.deny</code>；<code>ask</code>→<code>ask</code></td></tr><tr><td><code>PostToolUse</code></td><td><code>tools/post-execute</code>（waterfall）</td><td><code>deny</code>→ block + feedback；否则走 <code>next()</code></td></tr><tr><td><code>Stop</code></td><td><code>agent/turn-stopping</code>（serial）</td><td>阻塞 Stop hook 的 reason 通过 <code>steer()</code> 逼出下一步</td></tr><tr><td><code>SubagentStart</code>/<code>SubagentStop</code></td><td><code>subagent/start</code>/<code>subagent/end</code>（emit）</td><td>additionalContext→<code>inject</code> 到 live 子代理 / observe-only</td></tr></tbody></table><p>多个文件 hook 挂同一 node 时<strong>串行、按 config 顺序</strong>跑，结果按 <code>hook-protocol</code> 的 <strong>most-restrictive</strong> 折叠。这就把 CC/Codex 那种&quot;denied / block-with-reason&quot;的 shell-hook，接进了 <code>dsh</code> 的 typed Decision 体系。</p><h3 id="桥的价值与边界-兼容路径-不是最佳做法" tabindex="-1">桥的价值与边界：兼容路径，不是最佳做法 <a class="header-anchor" href="#桥的价值与边界-兼容路径-不是最佳做法" aria-label="Permalink to &quot;桥的价值与边界：兼容路径，不是最佳做法&quot;">​</a></h3><p>为什么要&quot;桥&quot;而不直接支持 <code>hooks.json</code>？<code>hooks-claude-code</code> README 里有一句很诚实的话：</p><blockquote><p>A native cordis plugin could do everything this bridge does — more powerfully, with typed returns and no serialization boundary.</p></blockquote><p>桥本身就是&quot;兼容路径&quot;——你有一段已经在 CC/Codex 里养好的 <code>hooks.json</code>，搬进 <code>dsh</code> 不用重写。<strong>真正要定制的地方，应该写成普通 cordis 插件，而不是指望桥必须覆盖你所有的边缘需求。</strong></p><h2 id="三、生态-八篇拼起来-dsh-的-引擎-立场" tabindex="-1">三、生态：八篇拼起来，<code>dsh</code> 的&quot;引擎&quot;立场 <a class="header-anchor" href="#三、生态-八篇拼起来-dsh-的-引擎-立场" aria-label="Permalink to &quot;三、生态：八篇拼起来，`dsh` 的&quot;引擎&quot;立场&quot;">​</a></h2><h3 id="一张对照表-同能不同构" tabindex="-1">一张对照表（同能不同构） <a class="header-anchor" href="#一张对照表-同能不同构" aria-label="Permalink to &quot;一张对照表（同能不同构）&quot;">​</a></h3><p>把前七篇的机制对齐到三个既有生态，你会看到 <code>dsh</code> 的每一项几乎都用了同一招——&quot;做成可换缝&quot;：</p><table tabindex="0"><thead><tr><th>主题</th><th>OpenCode</th><th>Codex</th><th>Claude Code</th><th><strong>DeepSeek Harness</strong></th></tr></thead><tbody><tr><td>主结构</td><td>插件 / Layer</td><td>multi-Agent</td><td>claude.md + Task</td><td><strong>everything is a plugin（vendored Cordis）</strong></td></tr><tr><td>长会话</td><td>压缩 2 级</td><td>压缩 3 级</td><td>压缩 5 级</td><td><strong>compaction / request-context / subagent 均做成可变缝</strong></td></tr><tr><td>hooks</td><td>无 shell-hook</td><td>部分 shell-hook</td><td><code>hooks.json</code> 原生</td><td><strong>hook-protocol 共享库 + CC/Codex 翻译桥</strong></td></tr><tr><td>自改</td><td>—</td><td>—</td><td>—</td><td><strong>自引用 cordis toolset（inspect/define/run/stop/undefine）</strong></td></tr></tbody></table><p><strong>核心差异一句话</strong>：</p><blockquote><p>三栏的 hooks 是&quot;产品自己的机制&quot;（CC 原生用自己的 <code>hooks.json</code>，OpenCode 没这块，Codex 只做部分）；而 <code>dsh</code> 把它也拆成&quot;一个 typed 事件 API + 外部协议翻译器&quot;。与技术无关、与产品立场有关：<code>dsh</code> 想当一条能接住别家既有投资的筐，而不是再闭门造一套。</p></blockquote><h3 id="dsh-的立场-可换不只用于-provider-还用于-接住别人的协议" tabindex="-1"><code>dsh</code> 的立场：可换不只用于 provider，还用于&quot;接住别人的协议&quot; <a class="header-anchor" href="#dsh-的立场-可换不只用于-provider-还用于-接住别人的协议" aria-label="Permalink to &quot;`dsh` 的立场：可换不只用于 provider，还用于&quot;接住别人的协议&quot;&quot;">​</a></h3><p>前七篇我们反复看到 <code>dsh</code>&quot;把 X 做成可换缝&quot;的习惯——capability seam 的每个（CompactionEngine / SubagentProvider / BashProvider……）。第八篇我们看到它其实收口成三个层次：</p><ol><li><strong>内部一致</strong>：所有东西（request、tool、hook、compaction、subagent）都回写到 session log + 都挂 typed 拦截点——可换 Provider。</li><li><strong>外部兼容</strong>：用「桥翻译既有 shell-hook 协议」接住 CC/Codex 的既有投资，不必从零重建。</li><li><strong>自反扩展</strong>：用「自引用 cordis toolset + vm 沙箱」给模型&quot;看自己 + 卸自己&quot;——但 trust 是 bash-equivalent，所以在生产上只做 opt-in。</li></ol><p>这三点叠起来，<code>dsh</code> 的成熟画像是：<strong>运行时用统一的 typed 事件表达一切可换能力；对外要么用 bridge 翻译既有 shell-hook，要么用 self-mod 从内长出能力。安全是&quot; sandbox 本身不是边界，只防意外&quot;，而完整的产品化由 opt-in 决定。</strong></p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>八篇走完，<code>dsh</code> 的骨架其实就是两根柱子——<strong>&quot;一切皆插件&quot;（Cordis）</strong> 和 <strong>&quot;一切变化都能写进 session surface&quot;（typed events）</strong>。最后一篇我们看到的是它两端用力：</p><ul><li><strong>向内</strong>：agent 能 inspect / mount / unmount 自己的临时插件（自引用 cordis toolset），但 trust = bash、不设安全边界；</li><li><strong>向外</strong>：能原样接住 Claude Code / Codex 的 <code>hooks.json</code>（typed hooks 桥），并诚实地说&quot;桥只是兼容路径，真要定制请写原生插件&quot;；</li><li><strong>成生态</strong>：能对齐三栏，是因为核心在生产一个&quot;typed event + surface + translation&quot;的开放平面，而不是另一套闭门的产品。</li></ul><p>一句话收束整栏：</p><blockquote><p><strong><code>dsh</code> 不是&quot;又一个 agent&quot;，它是一套由「插件 runtime + 可变缝 + 自改 + 桥接生态」组成、且每样都能可换可卸可追溯的引擎。</strong> 你能看得见自己、改得动自己、卸得下自己——也能把别家的壳接进自己的平面。</p></blockquote><p>至此，<code>DeepSeek Harness 源码精读</code> 八篇完结，感谢读完。</p><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>',61)),r(t,{questions:e})])}}});export{u as __pageData,p as default};
